const out = [];
const seen = {};
for (const item of $input.all()) {
  const b = item.json || {};
  for (const p of (b.projects || [])) {
    const pid = p.project_id ? String(p.project_id) : '';
    if (!pid || seen[pid]) continue;
    seen[pid] = true;
    out.push({ json: { projectId: pid, projectName: p.name || '' } });
  }
}
return out;

const TAG = 'to_review';
const UNASSIGNED_TAG = 'review_unassigned';
const SOURCE_PREFIX = 'en';
const MAX_KEYS_PER_TASK = 500;

const meta = {};
for (const p of $('Flatten Projects').all()) {
  const j = p.json || {};
  meta[String(j.projectId)] = j.projectName || '';
}

const byProject = {};
const fetchProblems = [];
for (const item of $input.all()) {
  const b = item.json || {};
  if (b.error) {
    fetchProblems.push(typeof b.error === 'string' ? b.error : JSON.stringify(b.error).slice(0, 300));
    continue;
  }
  const pid = b.project_id ? String(b.project_id) : '';
  if (!pid) continue;
  if (!byProject[pid]) byProject[pid] = { keys: [], contributors: [] };
  if (Array.isArray(b.keys)) byProject[pid].keys = byProject[pid].keys.concat(b.keys);
  if (Array.isArray(b.contributors)) byProject[pid].contributors = byProject[pid].contributors.concat(b.contributors);
}

const isSource = (iso) => String(iso || '').toLowerCase().indexOf(SOURCE_PREFIX) === 0;
const isEmpty = (v) => {
  if (v === null || v === undefined || v === '') return true;
  if (typeof v === 'object') return Object.keys(v).every((k) => !v[k]);
  return false;
};

const dueDate = $now.plus({ days: 5 }).set({ hour: 17, minute: 0, second: 0, millisecond: 0 }).toFormat('yyyy-MM-dd HH:mm:ss');
const runDate = $now.toFormat('yyyy-MM-dd');
const out = [];

for (const pid of Object.keys(byProject)) {
  const data = byProject[pid];
  if (!data.keys.length) continue;

  const pool = {};
  for (const c of data.contributors) {
    if (c.is_admin === true) continue;
    if (c.is_reviewer !== true) continue;
    for (const l of (c.languages || [])) {
      if (l.is_writable !== true) continue;
      const iso = String(l.lang_iso || '');
      if (!iso || isSource(iso)) continue;
      if (!pool[iso]) pool[iso] = [];
      if (pool[iso].indexOf(c.user_id) === -1) pool[iso].push(c.user_id);
    }
  }

  const langNeed = {};
  const keyEntries = [];
  let skippedUntranslated = 0;
  for (const k of data.keys) {
    let qualifies = false;
    for (const t of (k.translations || [])) {
      const iso = String(t.language_iso || '');
      if (!iso || isSource(iso)) continue;
      if (isEmpty(t.translation)) continue;
      if (t.is_reviewed === true && t.is_unverified !== true) continue;
      qualifies = true;
      langNeed[iso] = (langNeed[iso] || 0) + 1;
    }
    if (qualifies) {
      keyEntries.push({ key_id: k.key_id, tags: Array.isArray(k.tags) ? k.tags : [] });
    } else {
      skippedUntranslated = skippedUntranslated + 1;
    }
  }
  if (!keyEntries.length) continue;

  const languages = [];
  const gaps = [];
  const gapLanguages = [];
  for (const iso of Object.keys(langNeed)) {
    if (pool[iso] && pool[iso].length) {
      languages.push({ language_iso: iso, users: pool[iso] });
    } else {
      gaps.push({ language_iso: iso, strings_needing_review: langNeed[iso] });
      gapLanguages.push(iso);
    }
  }
  if (!languages.length) continue;

  const chunkCount = Math.ceil(keyEntries.length / MAX_KEYS_PER_TASK);
  for (let c = 0; c < chunkCount; c++) {
    const slice = keyEntries.slice(c * MAX_KEYS_PER_TASK, (c + 1) * MAX_KEYS_PER_TASK);
    const keyIds = [];
    for (const e of slice) keyIds.push(Number(e.key_id));
    const suffix = chunkCount > 1 ? ' (part ' + (c + 1) + '/' + chunkCount + ')' : '';
    const langList = [];
    for (const l of languages) langList.push(l.language_iso);
    out.push({ json: {
      projectId: pid,
      projectName: meta[pid] || '',
      taskTitle: 'Weekly review ' + runDate + ' - ' + (meta[pid] || pid) + suffix,
      taskDescription: 'Auto-created by n8n from keys tagged ' + TAG + '. ' + keyIds.length + ' keys, ' + languages.length + ' languages (' + langList.join(', ') + '). Due ' + dueDate + '. Keys are untagged once this task exists; languages with no eligible reviewer are tagged ' + UNASSIGNED_TAG + ' instead.',
      dueDate: dueDate,
      keyIds: keyIds,
      keyTags: slice,
      languages: languages,
      languageCount: languages.length,
      gaps: gaps,
      gapLanguages: gapLanguages,
      skippedUntranslatedKeys: skippedUntranslated,
      chunk: c + 1,
      chunkCount: chunkCount,
      fetchProblems: fetchProblems
    } });
  }
}
return out;

const r = $json || {};
const plan = $('Build Review Task Plans').item.json || {};
const task = r.task || {};
const ok = !!task.task_id;
let errText = null;
if (!ok) {
  if (r.error) errText = typeof r.error === 'string' ? r.error : JSON.stringify(r.error).slice(0, 400);
  else errText = JSON.stringify(r).slice(0, 400);
}
return { json: {
  ok: ok,
  taskId: task.task_id || null,
  projectId: plan.projectId,
  projectName: plan.projectName,
  taskTitle: plan.taskTitle,
  keyCount: (plan.keyIds || []).length,
  languageCount: plan.languageCount || 0,
  gapLanguages: plan.gapLanguages || [],
  keyTags: ok ? (plan.keyTags || []) : [],
  error: errText
} };

const TAG = 'to_review';
const UNASSIGNED_TAG = 'review_unassigned';
const BATCH = 50;
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.ok) continue;
  const flagUnassigned = (j.gapLanguages || []).length > 0;
  const updates = [];
  for (const k of (j.keyTags || [])) {
    const tags = [];
    for (const t of (k.tags || [])) {
      if (t !== TAG) tags.push(t);
    }
    if (flagUnassigned && tags.indexOf(UNASSIGNED_TAG) === -1) tags.push(UNASSIGNED_TAG);
    updates.push({ key_id: Number(k.key_id), tags: tags, merge_tags: false });
  }
  for (let i = 0; i < updates.length; i = i + BATCH) {
    out.push({ json: {
      projectId: j.projectId,
      projectName: j.projectName,
      taskId: j.taskId,
      keys: updates.slice(i, i + BATCH)
    } });
  }
}
return out;

const created = [];
const failed = [];
const gaps = [];
for (const item of $('Confirm Task Created').all()) {
  const j = item.json || {};
  if (j.ok) {
    created.push({ project: j.projectName || j.projectId, taskId: j.taskId, keys: j.keyCount, languages: j.languageCount });
  } else {
    failed.push({ project: j.projectName || j.projectId, error: j.error });
  }
  for (const iso of (j.gapLanguages || [])) {
    gaps.push({ project: j.projectName || j.projectId, language: iso });
  }
}
let untagged = 0;
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.keys)) untagged = untagged + j.keys.length;
}
return [{ json: {
  runAt: $now.toISO(),
  tasksCreated: created.length,
  tasksFailed: failed.length,
  keysUntagged: untagged,
  created: created,
  failed: failed,
  languagesWithNoEligibleReviewer: gaps
} }];
